create table public.prospectos(
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), contacto_id uuid not null references contactos(id), empresa_id uuid references empresas(id), segmento text, fuente text, campana text, necesidad_principal text not null, producto_interes_id uuid, ubicacion_proyecto text, metros_cuadrados_estimados numeric(12,2), tipo_proyecto text, fecha_ingreso date not null default current_date, estado text not null default 'Prospecto nuevo', temperatura_comercial text not null default 'Tibia', puntaje_comercial int check(puntaje_comercial between 0 and 100), ejecutivo_responsable_id uuid not null references profiles(id), proxima_accion text, fecha_proxima_accion timestamptz, observaciones text, convertido boolean not null default false, oportunidad_convertida_id uuid references oportunidades(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table public.controlled_lists(
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), tipo text not null, codigo text not null, nombre text not null, descripcion text, orden int not null default 0, color text, estado text not null default 'activo', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,tipo,codigo)
);
create table public.activities(
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), contacto_id uuid not null references contactos(id), empresa_id uuid references empresas(id), oportunidad_id uuid references oportunidades(id), proyecto_id uuid references proyectos(id), cotizacion_id uuid references cotizaciones(id), tipo_actividad text not null, fecha_hora_inicio timestamptz not null, fecha_hora_fin timestamptz, duracion_minutos int, estado text not null default 'pendiente', resultado text, descripcion text, proxima_accion text, fecha_proxima_accion timestamptz, ejecutivo_responsable_id uuid not null references profiles(id), origen_registro text not null default 'manual', import_row_id uuid, created_by uuid not null references profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.tasks(
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), titulo text not null, descripcion text, contacto_id uuid not null references contactos(id), empresa_id uuid references empresas(id), oportunidad_id uuid references oportunidades(id), proyecto_id uuid references proyectos(id), cotizacion_id uuid references cotizaciones(id), responsable_id uuid not null references profiles(id), tipo text not null, prioridad text not null default 'media', fecha_inicio timestamptz, fecha_hora_vencimiento timestamptz not null, estado text not null default 'pendiente', recordatorio_minutos int, sincronizado_google boolean not null default false, google_calendar_id text, google_event_id text, google_sync_status text, google_sync_error text, google_last_sync_at timestamptz, idempotency_key text not null unique, origen_registro text not null default 'manual', fecha_finalizacion timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create or replace function public.can_view_owner(owner_id uuid) returns boolean language sql stable security definer set search_path=public as $$select current_role() in ('admin','jefatura_comercial') or owner_id=auth.uid()$$;
create or replace function public.can_write_owner(owner_id uuid) returns boolean language sql stable security definer set search_path=public as $$select current_role() in ('admin','jefatura_comercial') or (current_role()='ejecutivo_comercial' and owner_id=auth.uid())$$;
create or replace function public.audit_row() returns trigger language plpgsql security definer set search_path=public as $$begin insert into audit_logs(organization_id,usuario_id,entidad_tipo,entidad_id,accion,valores_anteriores,valores_nuevos) values(coalesce(new.organization_id,old.organization_id),auth.uid(),TG_TABLE_NAME,coalesce(new.id,old.id),TG_OP,case when TG_OP<>'INSERT' then to_jsonb(old) end,case when TG_OP<>'DELETE' then to_jsonb(new) end);return coalesce(new,old);end$$;
create trigger audit_empresas after insert or update or delete on empresas for each row execute function audit_row();
create trigger audit_contactos after insert or update or delete on contactos for each row execute function audit_row();
create trigger audit_proyectos after insert or update or delete on proyectos for each row execute function audit_row();
create trigger audit_oportunidades after insert or update or delete on oportunidades for each row execute function audit_row();
create trigger audit_cotizaciones after insert or update or delete on cotizaciones for each row execute function audit_row();
alter table prospectos enable row level security; alter table controlled_lists enable row level security; alter table activities enable row level security; alter table tasks enable row level security;
create policy prospectos_read on prospectos for select using(organization_id=current_org() and can_view_owner(ejecutivo_responsable_id));
create policy prospectos_write on prospectos for all using(organization_id=current_org() and can_write_owner(ejecutivo_responsable_id)) with check(organization_id=current_org() and can_write_owner(ejecutivo_responsable_id));
create policy lists_read on controlled_lists for select using(organization_id=current_org());
create policy lists_admin on controlled_lists for all using(organization_id=current_org() and current_role()='admin') with check(organization_id=current_org() and current_role()='admin');
create policy activities_read on activities for select using(organization_id=current_org() and can_view_owner(ejecutivo_responsable_id));
create policy activities_write on activities for all using(organization_id=current_org() and can_write_owner(ejecutivo_responsable_id)) with check(organization_id=current_org() and can_write_owner(ejecutivo_responsable_id));
create policy tasks_read on tasks for select using(organization_id=current_org() and can_view_owner(responsable_id));
create policy tasks_write on tasks for all using(organization_id=current_org() and can_write_owner(responsable_id)) with check(organization_id=current_org() and can_write_owner(responsable_id));
create index idx_quote_number on cotizaciones(organization_id,numero_cotizacion_normalizado);
create index idx_tasks_due on tasks(organization_id,responsable_id,estado,fecha_hora_vencimiento);
create index idx_activities_quote on activities(organization_id,cotizacion_id,fecha_hora_inicio desc);
